-- VTS Energy & Security V2 Supabase schema
create extension if not exists pgcrypto;
create table if not exists public.admin_users(user_id uuid primary key references auth.users(id) on delete cascade,display_name text,created_at timestamptz default now());
create table if not exists public.site_settings(id bigint primary key default 1 check(id=1),company_name text not null,legal_name text not null,registration_number text not null,phone text not null,phone2 text,whatsapp text not null,sales_email text not null,info_email text not null,address text not null,coverage text not null,mission text not null,vision text not null,values text not null,updated_at timestamptz default now());
create table if not exists public.categories(id bigint generated by default as identity primary key,name text unique not null,active boolean default true,display_order int default 0,created_at timestamptz default now());
create table if not exists public.products(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,category_id bigint references public.categories(id) on delete set null,category text,short_description text not null default '',description text not null default '',price numeric(12,2),price_type text not null default 'quote' check(price_type in('fixed','starting','quote')),image_path text,image_url text,specifications jsonb not null default '[]',features jsonb not null default '[]',featured boolean default false,active boolean default true,display_order int default 0,is_demo boolean default true,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.services(id uuid primary key default gen_random_uuid(),name text not null,category text not null check(category in('Energy Solutions','Digital Security Solutions')),description text not null,image text,active boolean default true,display_order int default 0,created_at timestamptz default now());
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.admin_users where user_id=auth.uid()); $$;
revoke all on function public.is_admin() from public; grant execute on function public.is_admin() to anon,authenticated;
alter table public.admin_users enable row level security; alter table public.site_settings enable row level security; alter table public.categories enable row level security; alter table public.products enable row level security; alter table public.services enable row level security;
drop policy if exists admin_users_select on public.admin_users; create policy admin_users_select on public.admin_users for select to authenticated using(user_id=auth.uid());
drop policy if exists settings_public_read on public.site_settings; create policy settings_public_read on public.site_settings for select to anon,authenticated using(true); drop policy if exists settings_admin_update on public.site_settings; create policy settings_admin_update on public.site_settings for update to authenticated using(public.is_admin()) with check(public.is_admin());
drop policy if exists categories_public_read on public.categories; create policy categories_public_read on public.categories for select to anon,authenticated using(active=true or public.is_admin()); drop policy if exists categories_admin_insert on public.categories; create policy categories_admin_insert on public.categories for insert to authenticated with check(public.is_admin()); drop policy if exists categories_admin_update on public.categories; create policy categories_admin_update on public.categories for update to authenticated using(public.is_admin()) with check(public.is_admin()); drop policy if exists categories_admin_delete on public.categories; create policy categories_admin_delete on public.categories for delete to authenticated using(public.is_admin());
drop policy if exists products_public_read on public.products; create policy products_public_read on public.products for select to anon,authenticated using(active=true or public.is_admin()); drop policy if exists products_admin_insert on public.products; create policy products_admin_insert on public.products for insert to authenticated with check(public.is_admin()); drop policy if exists products_admin_update on public.products; create policy products_admin_update on public.products for update to authenticated using(public.is_admin()) with check(public.is_admin()); drop policy if exists products_admin_delete on public.products; create policy products_admin_delete on public.products for delete to authenticated using(public.is_admin());
drop policy if exists services_public_read on public.services; create policy services_public_read on public.services for select to anon,authenticated using(active=true or public.is_admin()); drop policy if exists services_admin_insert on public.services; create policy services_admin_insert on public.services for insert to authenticated with check(public.is_admin()); drop policy if exists services_admin_update on public.services; create policy services_admin_update on public.services for update to authenticated using(public.is_admin()) with check(public.is_admin()); drop policy if exists services_admin_delete on public.services; create policy services_admin_delete on public.services for delete to authenticated using(public.is_admin());
insert into storage.buckets(id,name,public) values('product-images','product-images',true) on conflict(id) do update set public=true;
drop policy if exists product_images_public_read on storage.objects; create policy product_images_public_read on storage.objects for select to public using(bucket_id='product-images'); drop policy if exists product_images_admin_insert on storage.objects; create policy product_images_admin_insert on storage.objects for insert to authenticated with check(bucket_id='product-images' and public.is_admin()); drop policy if exists product_images_admin_update on storage.objects; create policy product_images_admin_update on storage.objects for update to authenticated using(bucket_id='product-images' and public.is_admin()) with check(bucket_id='product-images' and public.is_admin()); drop policy if exists product_images_admin_delete on storage.objects; create policy product_images_admin_delete on storage.objects for delete to authenticated using(bucket_id='product-images' and public.is_admin());
