create or replace function public.touch_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end; $$;
drop trigger if exists products_touch_updated_at on public.products; create trigger products_touch_updated_at before update on public.products for each row execute function public.touch_updated_at(); drop trigger if exists settings_touch_updated_at on public.site_settings; create trigger settings_touch_updated_at before update on public.site_settings for each row execute function public.touch_updated_at();
